### Search keywords

schedule command tasklist input output io

### Latest version

- [x] I have tested the latest version

### Summary

add named inputs and outputs to json and yaml task definitions.. the inputs can reference outputs from tasks in the same list which will change  

### Examples


```json
{
  "tasks": [
    {
      "name": "build tech updates email",
      "prompt": "create a reading list for any new technology news that seems relevant to me and send me an email with the list",
      "inputs": [{

         "url": "https://myfavoritetechnewssource.com"
}],
       "outputs": [{
          "email": {
    headers: [  # in an array since order matters
        { name: 'Subject', value: 'An email' },
        { name: 'Date',    value: 'Thu, 4 Mar 2010 15:35:32 -0800' },
        { name: 'From',    value: 'george@foo.com' },
        { name: 'To',      value: 'paul@goo.com' }
        { name: 'Sender',  value: 'paul@goo.com' }
        { name: 'Reply-to', value: 'paul@goo.com' }
    ],
    from: 'From blah blah...',
    body: {
        type: 'multipart/alternative,
        parts: [
            {
                id: 'partid-1',
                type: 'text/plain',
                sections: [
                    {
                        type: 'greeting',
                        text: 'Dear Jason,'
                    },
                    {
                        type: 'normal',
                        text: ["This is an ", {type: 'url', href: 'http://foo.com, text: "URL"}, ", that I have embedded in some text."]
                    },
                    {
                        type: quoted-section,
                        text: "Something worth quoting."
                    },
                    {
                        type: quoted-section,
                        body: {
                            headers: [
                            { name: 'Subject', value: 'Hey there' },
                            { name: 'Date', ... } 
                            ],
                            body: {
                                type: 'text/plain',
                                text:  'Hi there'
                            }
                        }
                    },
                    {
                        type: 'signature',
                        text: '...'
                    }
                ]
            },
            {
                id: 'id',
                type: 'text/html'
                text: '<bold>Dear Jason</bold>, <br/>This is a test.',
            },
        ]
    }
}

}],
    {
      "name": "schedule prep",
      "prompt": "read my scheudle for the next 3 days and give me a list of things that i should prepare for today in order to have successful tasks"
    }
  ]
}
```

yaml:
```yaml
---
tasks:
- name: build tech updates email
  prompt: create a reading list for any new technology news that seems relevant to
    me and send me an email with the list
- name: schedule prep
  prompt: read my scheudle for the next 3 days and give me a list of things that i
    should prepare for today in order to have successful tasks
```


